  Terrain.EMPTY_WELL,
  Terrain.ENTRANCE,
  Terrain.EXIT,
  Terrain.EMBERS,
  Terrain.PEDESTAL,
  Terrain.EMPTY_SP,
  Terrain.SECRET_TRAP,
  Terrain.TRAP,
  Terrain.INACTIVE_TRAP,
  Terrain.EMPTY_DECO,
  Terrain.WELL,
  Terrain.WATER
